"use strict";

exports.httpRequest = function (req) {
  return req.httpRequest;
}

exports.host = function (req) {
  return req.host;
}

exports.resource = function (req) {
  return req.resource;
}

exports.resourceURL = function (req) {
  return req.resourceURL;
}

exports.remoteAddress = function (req) {
  return req.remoteAddress;
}

exports.webSocketVersion = function (req) {
  return req.webSocketVersion;
}

exports.origin = function (req) {
  return req.origin;
}

exports.requestedProtocols = function (req) {
  return req.requestedProtocols;
}

exports.accept = function (req) {
  return function (acceptedProtocol) {
    return function (allowedOrigin) {
      return function () {
        return req.accept(acceptedProtocol, allowedOrigin);
      }
    }
  }
}

exports.reject = function (req) {
  return function (httpStatus) {
    return function (reason) {
      return function () {
        req.reject(httpStatus, reason);
      }
    }
  }
}

exports.onRequestAccepted = function (req) {
  return function (callback) {
    return function () {
      req.on("requestAccepted", function(conn) {
        callback(conn)();
      });
    }
  }
}

exports.onRequestRejected = function (req) {
  return function (callback) {
    return function () {
      req.on("requestRejected", function() {
        callback();
      });
    }
  }
}

"use strict";

exports.closeDescription = function (conn) {
  return conn.closeDescription;
}

exports.closeReasonCode = function (conn) {
  return conn.closeReasonCode;
}

exports.protocol = function (conn) {
  return conn.protocol;
}

exports.remoteAddress = function (conn) {
  return conn.remoteAddress;
}

exports.webSocketVersion = function (conn) {
  return conn.webSocketVersion;
}

exports.connected = function (conn) {
  return conn.connected;
}

exports.closeWithReason = function (conn) {
  return function (reasonCode) {
    return function (description) {
      return function () {
        conn.close(reasonCode, description);
      }
    }
  }
}

exports.close = function (conn) {
  return function () {
    conn.close();
  }
}

exports.drop = function (conn) {
  return function (reasonCode) {
    return function (description) {
      return function () {
        conn.drop(reasonCode, description);
      }
    }
  }
}

exports.sendUTF = function (conn) {
  return function (msg) {
    return function () {
      conn.sendUTF(msg);
    }
  }
}

exports.sendBytes = function (conn) {
  return function (buffer) {
    return function () {
      conn.sendBytes(buffer);
    }
  }
}

exports.ping = function (conn) {
  return function (buffer) {
    return function () {
      conn.ping(buffer);
    }
  }
}

exports.pong = function (conn) {
  return function (buffer) {
    return function () {
      conn.pong(buffer);
    }
  }
}

exports.sendFrame = function (conn) {
  return function (frame) {
    return function () {
      conn.sendFrame(frame);
    }
  }
}

exports.onMessageImpl = function (Left) {
  return function (Right) {
    return function (conn) {
      return function (callback) {
        return function () {
          conn.on("message", function (msg) {
            if (msg.type == "utf8") {
              callback(Left(msg))();
              return;
            }
            callback(Right(msg))();
          })
        }
      }
    }
  }
}

exports.onFrame = function (conn) {
  return function (callback) {
    return function () {
      conn.on("frame", function (frame) {
        callback(frame)();
      })
    }
  }
}

exports.onClose = function (conn) {
  return function (callback) {
    return function () {
      conn.on("close", function(reasonCode, description) {
        callback(reasonCode)(description)();
      })
    }
  }
}

exports.onError = function (conn) {
  return function (callback) {
    return function () {
      conn.on("error", function (err) {
        callback(err)();
      })
    }
  }
}

exports.onPing = function (conn) {
  return function (callback) {
    return function () {
      conn.on("ping", function(cancel, data) {
        callback(data)(cancel)();
      })
    }
  }
}

exports.onPong = function (conn) {
  return function (callback) {
    return function () {
      conn.on("pong", function (data) {
        callback(data)();
      })
    }
  }
}

"use strict";

var WSServer = require("websocket").server;

exports.newWebsocketServer = function (config) {
  return function () {
    return new WSServer(config);
  }
}

exports.onRequest = function (server) {
  return function (callback) {
    return function () {
      server.on("request", function (req) {
        callback(req)();
      })
    }
  }
}

exports.onConnect = function (server) {
  return function (callback) {
    return function () {
      server.on("connect", function (conn) {
        callback(conn)();
      })
    }
  }
}

exports.onClose = function (server) {
  return function (callback) {
    return function () {
      server.on("close", function (conn, reason, description) {
        callback(conn)(reason)(description)();
      })
    }
  }
}

"use strict";

var WSFrame = require("websocket").frame;

exports.newWebsocketFrame = function () {
  return new WSFrame();
}

exports.unsafeGet = function (frame) {
  return function (prop) {
    return frame[prop];
  }
}

exports.unsafeSet = function (frame) {
  return function (prop) {
    return function (val) {
      return function () {
        frame[prop] = val;
      }
    }
  }
}

"use strict";

var WSClient = require("websocket").client;

exports.newWebsocketClient = function (config) {
  return function () {
    return new WSClient(config);
  }
}

exports.connect = function (client) {
  return function (requestUrl) {
    return function (requestProtocols) {
      return function (origin) {
        return function (headers) {
          return function (requestOptions) {
            return function () {
              client.connect(requestUrl, requestProtocols, origin, headers, requestOptions);
            }
          }
        }
      }
    }
  }
}

exports.abort = function (client) {
  return function () {
    client.abort();
  }
}

exports.onConnect = function (client) {
  return function (callback) {
    return function () {
      client.on("connect", function (conn) {
        callback(conn)();
      })
    }
  }
}

exports.onConnectFailed = function (client) {
  return function (callback) {
    return function () {
      client.on("connectFailed", function (errorDescription) {
        callback(errorDescription)();
      })
    }
  }
}

exports.onHttpResponse = function (client) {
  return function (callback) {
    return function () {
      client.on("httpResponse", function (response, webSocketClient) {
        callback(response)(webSocketClient)();
      })
    }
  }
}
